gaBR(){return"\u0421\u0435\u0440\u0432\u0435\u0440 \u043c\u0435\u043d\u0435\u043d \u0431\u0430\u0439\u043b\u0430\u043d\u044b\u0448 \u0442\u04af\u0437\u04af\u043b\u0433\u04e9\u043d \u0436\u043e\u043a. \u0422\u04af\u0437\u043c\u04e9\u043a\u0442\u04af\u043d \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442 \u0431\u0430\u0439\u043b\u0430\u043d\u044b\u0448\u044b\u043d \u0442\u0435\u043a\u0448\u0435\u0440\u0438\u043f, \u043a\u0430\u0439\u0440\u0430 \u0430\u0440\u0430\u043a\u0435\u0442 \u043a\u044b\u043b\u044b\u04a3\u044b\u0437."},
gaBU(){return"\u0421\u0435\u0440\u0432\u0435\u0440 \u04e9\u0437 \u0443\u0431\u0430\u0433\u044b\u043d\u0434\u0430 \u0436\u043e\u043e\u043f \u0431\u0435\u0440\u0433\u0435\u043d \u0436\u043e\u043a. \u0411\u0438\u0440 \u0430\u0437 \u043a\u04af\u0442\u04af\u043f, \u043a\u0430\u0439\u0440\u0430 \u0436\u04e9\u043d\u04e9\u0442\u04af\u04af\u0434\u04e9\u043d \u043c\u0443\u0440\u0443\u043d \u0438\u0448\u0442\u0438\u043d \u0436\u044b\u0439\u044b\u043d\u0442\u044b\u0433\u044b\u043d \u0442\u0435\u043a\u0448\u0435\u0440\u0438\u04a3\u0438\u0437."},
